ALTER TABLE "mira_browser_processes" DROP CONSTRAINT "mira_browser_process_phase", ADD CONSTRAINT "mira_browser_process_phase" CHECK (("phase" IN ('reserved','creating','rejected') AND "container_id" IS NULL AND ("phase"<>'rejected' OR "state"<>'active')) OR ("phase"='created' AND "container_id" IS NOT NULL AND "container_id" ~ '^[a-f0-9]{64}$'));--> statement-breakpoint
ALTER TABLE "mira_browser_processes" DROP CONSTRAINT "mira_browser_process_state", ADD CONSTRAINT "mira_browser_process_state" CHECK (("state" IN ('active','cleanup') AND "removed_at" IS NULL AND "cleanup_evidence" IS NULL) OR ("state"='removed' AND "removed_at" IS NOT NULL AND "cleanup_evidence" IS NOT NULL AND (("phase"='reserved' AND "cleanup_evidence"='not-created') OR ("phase"='rejected' AND "cleanup_evidence"='rejected') OR ("phase"='created' AND "cleanup_evidence" IN ('removed','absent')))));